const text = helpers.getAllText();
const cursorPos = helpers.getCursorPosition();
const before = text.substring(0, cursorPos);
const lines = text.substring(cursorPos).split('\n');
let blockStart = -1, blockEnd = -1;
for (let i = 0; i < lines.length; i++) {
  if (lines[i].trim().startsWith('```yaml')) {
    blockStart = i;
    for (let j = i + 1; j < lines.length; j++) {
      if (lines[j].trim().startsWith('```')) {
        blockEnd = j;
        break;
      }
    }
    break;
  }
}
if (blockStart !== -1 && blockEnd !== -1) {
  for (let i = blockStart + 1; i < blockEnd; i++) {
    const line = lines[i];
    const colonIndex = line.indexOf(':');
    if (colonIndex !== -1) {
      const key = line.substring(0, colonIndex).trim();
      const open = line.indexOf('[[', colonIndex);
      const close = line.indexOf(']]', open);
      if (open !== -1 && close !== -1) {
        lines[i] = line.substring(0, open + 2) + '{{' + key + '}}' + line.substring(close);
      }
    }
  }
  helpers.replaceAllText(before + lines.join('\n'));
}

const lines = helpers.getLines();
const cursorPos = helpers.getCursorPosition();
const textBeforeCursor = helpers.getAllText().slice(0, cursorPos);
const cursorLine = textBeforeCursor.split('\n').length;
const vals = [];

let targetStart = -1;
let targetEnd = -1;
for (let i = cursorLine; i < lines.length; i++) {
  const trimmed = lines[i].trim();
  if (trimmed.startsWith('```yaml')) {
    targetStart = i;
    for (let j = i + 1; j < lines.length; j++) {
      if (lines[j].trim().startsWith('```')) {
        targetEnd = j;
        break;
      }
    }
    break;
  }
}

if (targetStart !== -1 && targetEnd !== -1) {
  for (let i = targetStart + 1; i < targetEnd; i++) {
    const text = lines[i];
    const colonIndex = text.indexOf(':');
    if (colonIndex !== -1) {
      let v = text.substring(colonIndex + 1).trim();
      v = v.replace(/^\[\[/, '').replace(/\]\]$/, '');
      if (v) vals.push(v);
    }
  }
  if (vals.length > 0) helpers.copyToClipboard(vals.join('\n'));
}
